/**
 * DevOpsDays Islamabad 2026 � I'm Attending Poster Generator
 * Pure Vanilla JavaScript Implementation
 *
 * Procedure:
 * 1. Upload picture first (auto-fits frame, no manual adjusters)
 * 2. Enter full name & designation or university name (+ / - font adjusters only)
 * 3. Preview live poster & download high-res PNG / share on LinkedIn
 */

(function () {
  'use strict';

  // ==========================================================================
  // Poster Geometry & Canvas Constants (1842 x 2304 native resolution)
  // ==========================================================================
  const CANVAS_WIDTH = 1842;
  const CANVAS_HEIGHT = 2304;

  // Exact coordinates of the central picture box measured from "final one.jfif"
  const PHOTO_BOX = {
    x: 612,
    y: 976,
    width: 648,
    height: 616,
    radius: 34,
    centerX: 936, // 612 + 648 / 2
    centerY: 1284 // 976 + 616 / 2
  };

  // Text bounds below the photo box (above footer at Y: 1940)
  const TEXT_BOUNDS = {
    centerX: 936,
    maxWidth: 1500,
    name: {
      centerY: 1715,
      maxHeight: 120,
      defaultSize: 76,
      minSize: 40,
      maxSize: 110,
      step: 2
    },
    designation: {
      topY: 1785,
      maxHeight: 130,
      defaultSize: 42,
      minSize: 24,
      maxSize: 64,
      step: 2,
      lineHeightMultiplier: 1.28
    }
  };

  // Embedded base64 poster template: loads in 0ms without CORS or file:// tainting
  const EMBEDDED_TEMPLATE_DATA_URL = 'data:image/jpeg;base64,';

  // ==========================================================================
  // Application State
  // ==========================================================================
  const state = {
    currentStep: 1, // 1: Upload, 2: Details, 3: Preview & Download
    templateImage: null,
    templateLoaded: false,

    // Uploaded photo (automatically fitted, no manual adjustments)
    photoImage: null,
    photoFileName: '',

    // Text inputs
    name: 'SYED MUHAMMAD ALI',
    nameSize: 76,

    designation: 'Principal DevOps Architect | AWS Hero\nCloud Platform Engineering',
    desigSize: 42
  };

  // ==========================================================================
  // DOM Elements
  // ==========================================================================
  const dom = {
    // Stepper Navigation Tabs
    tabStep1: document.getElementById('tabStep1'),
    tabStep2: document.getElementById('tabStep2'),
    tabStep3: document.getElementById('tabStep3'),
    connector1: document.getElementById('connector1'),
    connector2: document.getElementById('connector2'),

    // Wizard Panels
    stepPanel1: document.getElementById('stepPanel1'),
    stepPanel2: document.getElementById('stepPanel2'),
    stepPanel3: document.getElementById('stepPanel3'),

    // Step 1: Upload
    imageInput: document.getElementById('imageInput'),
    uploadDropzone: document.getElementById('uploadDropzone'),
    photoStatusBar: document.getElementById('photoStatusBar'),
    photoFileName: document.getElementById('photoFileName'),
    btnChangePhoto: document.getElementById('btnChangePhoto'),
    btnUseDemoPhoto: document.getElementById('btnUseDemoPhoto'),
    btnProceedToDetails: document.getElementById('btnProceedToDetails'),

    // Step 2: Name & Designation / University
    nameInput: document.getElementById('nameInput'),
    nameSizeValue: document.getElementById('nameSizeValue'),
    btnNameMinus: document.getElementById('btnNameMinus'),
    btnNamePlus: document.getElementById('btnNamePlus'),

    desigInput: document.getElementById('desigInput'),
    desigSizeValue: document.getElementById('desigSizeValue'),
    btnDesigMinus: document.getElementById('btnDesigMinus'),
    btnDesigPlus: document.getElementById('btnDesigPlus'),

    btnBackToPhoto: document.getElementById('btnBackToPhoto'),
    btnProceedToPreview: document.getElementById('btnProceedToPreview'),

    // Step 3: Preview & Download
    canvas: document.getElementById('posterCanvas'),
    canvasWrapper: document.getElementById('canvasWrapper'),
    btnQuickNameMinus: document.getElementById('btnQuickNameMinus'),
    btnQuickNamePlus: document.getElementById('btnQuickNamePlus'),
    quickNameSize: document.getElementById('quickNameSize'),

    btnQuickDesigMinus: document.getElementById('btnQuickDesigMinus'),
    btnQuickDesigPlus: document.getElementById('btnQuickDesigPlus'),
    quickDesigSize: document.getElementById('quickDesigSize'),

    btnDownload: document.getElementById('btnDownload'),
    btnLinkedInShare: document.getElementById('btnLinkedInShare'),
    btnEditDetails: document.getElementById('btnEditDetails'),
    btnChangePhotoFromPreview: document.getElementById('btnChangePhotoFromPreview'),
    btnResetAll: document.getElementById('btnResetAll'),

    // LinkedIn Modal
    linkedInModal: document.getElementById('linkedInModal'),
    btnCloseModal: document.getElementById('btnCloseModal'),
    btnDoneModal: document.getElementById('btnDoneModal'),
    btnModalDownload: document.getElementById('btnModalDownload'),
    btnCopyCaption: document.getElementById('btnCopyCaption'),
    copyTextState: document.getElementById('copyTextState'),
    captionText: document.getElementById('captionText'),

    // Toast Container
    toastContainer: document.getElementById('toastContainer')
  };

  const ctx = dom.canvas.getContext('2d', { alpha: false });

  // ==========================================================================
  // Initialization & Template Loading
  // ==========================================================================
  function init() {
    dom.nameInput.value = state.name;
    dom.desigInput.value = state.designation;
    updateSizeDisplays();

    setupEventListeners();
    loadTemplate();
    updateStepView(1);
  }

  function loadTemplate() {
    const img = new Image();
    img.onload = function () {
      state.templateImage = img;
      state.templateLoaded = true;
      renderCanvas();
    };
    img.onerror = function () {
      // Fallback to relative file path if data URL fails
      const fallback = new Image();
      fallback.onload = function () {
        state.templateImage = fallback;
        state.templateLoaded = true;
        renderCanvas();
      };
      fallback.onerror = function () {
        showToast('Template image could not be loaded.', 'error');
      };
      fallback.src = 'final one.jfif';
    };

    // Load instantly from embedded high-res data URL
    img.src = EMBEDDED_TEMPLATE_DATA_URL;
  }

  // ==========================================================================
  // Event Listeners
  // ==========================================================================
  function setupEventListeners() {
    // Stepper Navigation Tabs
    dom.tabStep1.addEventListener('click', () => updateStepView(1));
    dom.tabStep2.addEventListener('click', () => {
      if (state.photoImage) updateStepView(2);
      else showToast('Please upload a picture first', 'info');
    });
    dom.tabStep3.addEventListener('click', () => {
      if (state.photoImage) updateStepView(3);
      else showToast('Please upload a picture first', 'info');
    });

    // Step 1 Events
    dom.uploadDropzone.addEventListener('click', () => dom.imageInput.click());
    dom.btnChangePhoto.addEventListener('click', () => dom.imageInput.click());
    dom.imageInput.addEventListener('change', handleFileSelect);

    ['dragenter', 'dragover'].forEach(eventName => {
      dom.uploadDropzone.addEventListener(eventName, (e) => {
        e.preventDefault();
        e.stopPropagation();
        dom.uploadDropzone.classList.add('dragover');
      });
    });

    ['dragleave', 'drop'].forEach(eventName => {
      dom.uploadDropzone.addEventListener(eventName, (e) => {
        e.preventDefault();
        e.stopPropagation();
        dom.uploadDropzone.classList.remove('dragover');
      });
    });

    dom.uploadDropzone.addEventListener('drop', (e) => {
      if (e.dataTransfer && e.dataTransfer.files && e.dataTransfer.files.length > 0) {
        processUploadedFile(e.dataTransfer.files[0]);
      }
    });

    window.addEventListener('paste', (e) => {
      const items = (e.clipboardData || e.originalEvent.clipboardData).items;
      for (let i = 0; i < items.length; i++) {
        if (items[i].type.indexOf('image') !== -1) {
          const file = items[i].getAsFile();
          processUploadedFile(file);
          showToast('Image pasted from clipboard!', 'success');
          break;
        }
      }
    });

    dom.btnUseDemoPhoto.addEventListener('click', loadDemoAvatar);
    dom.btnProceedToDetails.addEventListener('click', () => updateStepView(2));

    // Step 2 Events
    dom.nameInput.addEventListener('input', (e) => {
      state.name = e.target.value;
      renderCanvas();
    });

    dom.desigInput.addEventListener('input', (e) => {
      state.designation = e.target.value;
      renderCanvas();
    });

    // Font +/- Steppers
    dom.btnNameMinus.addEventListener('click', () => changeNameSize(-TEXT_BOUNDS.name.step));
    dom.btnNamePlus.addEventListener('click', () => changeNameSize(TEXT_BOUNDS.name.step));
    dom.btnDesigMinus.addEventListener('click', () => changeDesigSize(-TEXT_BOUNDS.designation.step));
    dom.btnDesigPlus.addEventListener('click', () => changeDesigSize(TEXT_BOUNDS.designation.step));

    dom.btnBackToPhoto.addEventListener('click', () => updateStepView(1));
    dom.btnProceedToPreview.addEventListener('click', () => updateStepView(3));

    // Step 3 Events
    dom.btnQuickNameMinus.addEventListener('click', () => changeNameSize(-TEXT_BOUNDS.name.step));
    dom.btnQuickNamePlus.addEventListener('click', () => changeNameSize(TEXT_BOUNDS.name.step));
    dom.btnQuickDesigMinus.addEventListener('click', () => changeDesigSize(-TEXT_BOUNDS.designation.step));
    dom.btnQuickDesigPlus.addEventListener('click', () => changeDesigSize(TEXT_BOUNDS.designation.step));

    dom.btnDownload.addEventListener('click', downloadPoster);
    dom.btnLinkedInShare.addEventListener('click', handleLinkedInShare);
    dom.btnEditDetails.addEventListener('click', () => updateStepView(2));
    dom.btnChangePhotoFromPreview.addEventListener('click', () => updateStepView(1));
    dom.btnResetAll.addEventListener('click', resetAll);

    // LinkedIn Modal Events
    dom.btnCloseModal.addEventListener('click', closeModal);
    dom.btnDoneModal.addEventListener('click', closeModal);
    dom.btnModalDownload.addEventListener('click', downloadPoster);
    dom.btnCopyCaption.addEventListener('click', copyShareCaption);
    dom.linkedInModal.addEventListener('click', (e) => {
      if (e.target === dom.linkedInModal) closeModal();
    });
  }

  // ==========================================================================
  // Step View Switcher
  // ==========================================================================
  function updateStepView(stepNumber) {
    state.currentStep = stepNumber;

    dom.stepPanel1.style.display = stepNumber === 1 ? 'block' : 'none';
    dom.stepPanel2.style.display = stepNumber === 2 ? 'block' : 'none';
    dom.stepPanel3.style.display = stepNumber === 3 ? 'block' : 'none';

    [dom.tabStep1, dom.tabStep2, dom.tabStep3].forEach((tab, index) => {
      const num = index + 1;
      tab.classList.remove('active', 'completed');
      if (num === stepNumber) {
        tab.classList.add('active');
      } else if (num < stepNumber || (num === 1 && state.photoImage)) {
        tab.classList.add('completed');
      }
    });

    dom.connector1.classList.toggle('completed', stepNumber >= 2);
    dom.connector2.classList.toggle('completed', stepNumber >= 3);

    if (stepNumber === 3) {
      renderCanvas();
    }

    window.scrollTo({ top: 0, behavior: 'smooth' });
  }

  // ==========================================================================
  // Font Size Steppers (+ and - buttons)
  // ==========================================================================
  function changeNameSize(delta) {
    state.nameSize = Math.max(TEXT_BOUNDS.name.minSize, Math.min(TEXT_BOUNDS.name.maxSize, state.nameSize + delta));
    updateSizeDisplays();
    renderCanvas();
  }

  function changeDesigSize(delta) {
    state.desigSize = Math.max(TEXT_BOUNDS.designation.minSize, Math.min(TEXT_BOUNDS.designation.maxSize, state.desigSize + delta));
    updateSizeDisplays();
    renderCanvas();
  }

  function updateSizeDisplays() {
    dom.nameSizeValue.textContent = state.nameSize + 'px';
    dom.quickNameSize.textContent = state.nameSize + 'px';

    dom.desigSizeValue.textContent = state.desigSize + 'px';
    dom.quickDesigSize.textContent = state.desigSize + 'px';
  }

  // ==========================================================================
  // File Upload Handling (Auto-Fit, No Manual Adjusters)
  // ==========================================================================
  function handleFileSelect(e) {
    if (e.target.files && e.target.files[0]) {
      processUploadedFile(e.target.files[0]);
    }
  }

  function processUploadedFile(file) {
    if (!file) return;

    const validTypes = ['image/jpeg', 'image/png', 'image/webp', 'image/jfif', 'image/jpg', 'image/gif'];
    const isImage = file.type ? validTypes.includes(file.type.toLowerCase()) : /\.(jpe?g|png|webp|jfif|gif)$/i.test(file.name);

    if (!isImage) {
      showToast('Please upload a valid image file (JPG, PNG, WEBP, or JFIF).', 'error');
      return;
    }

    if (file.size > 15 * 1024 * 1024) {
      showToast('File size exceeds 15MB. Please choose a smaller photo.', 'error');
      return;
    }

    const reader = new FileReader();
    reader.onload = function (e) {
      const img = new Image();
      img.onload = function () {
        state.photoImage = img;
        state.photoFileName = file.name;

        updatePhotoStatusUI(true);
        renderCanvas();
        showToast('Photo uploaded and auto-fitted perfectly!', 'success');

        setTimeout(() => {
          updateStepView(2);
        }, 700);
      };
      img.onerror = function () {
        showToast('Failed to load image. The file may be corrupted.', 'error');
      };
      img.src = e.target.result;
    };
    reader.readAsDataURL(file);
  }

  function updatePhotoStatusUI(hasPhoto) {
    if (hasPhoto) {
      dom.uploadDropzone.style.display = 'none';
      dom.photoStatusBar.style.display = 'flex';
      dom.photoFileName.textContent = state.photoFileName || 'profile-picture.jpg';
      dom.btnProceedToDetails.disabled = false;
    } else {
      dom.uploadDropzone.style.display = 'block';
      dom.photoStatusBar.style.display = 'none';
      dom.btnProceedToDetails.disabled = true;
    }
  }

  function loadDemoAvatar() {
    const avatarCanvas = document.createElement('canvas');
    avatarCanvas.width = 600;
    avatarCanvas.height = 600;
    const actx = avatarCanvas.getContext('2d');

    const bgGrad = actx.createLinearGradient(0, 0, 600, 600);
    bgGrad.addColorStop(0, '#1e103f');
    bgGrad.addColorStop(0.5, '#3b1260');
    bgGrad.addColorStop(1, '#0e0724');
    actx.fillStyle = bgGrad;
    actx.fillRect(0, 0, 600, 600);

    actx.strokeStyle = 'rgba(217, 70, 239, 0.45)';
    actx.lineWidth = 5;
    actx.beginPath();
    actx.arc(300, 300, 245, 0, Math.PI * 2);
    actx.stroke();

    actx.fillStyle = '#fce7f3';
    actx.beginPath();
    actx.arc(300, 240, 95, 0, Math.PI * 2);
    actx.fill();

    actx.fillStyle = '#0f172a';
    actx.beginPath();
    actx.roundRect(220, 220, 70, 35, 6);
    actx.roundRect(310, 220, 70, 35, 6);
    actx.fill();
    actx.strokeStyle = '#d946ef';
    actx.lineWidth = 3;
    actx.stroke();
    actx.beginPath();
    actx.moveTo(290, 235);
    actx.lineTo(310, 235);
    actx.stroke();

    actx.fillStyle = '#ec4899';
    actx.beginPath();
    actx.ellipse(300, 480, 180, 140, 0, 0, Math.PI * 2);
    actx.fill();

    actx.fillStyle = '#1e1b4b';
    actx.beginPath();
    actx.moveTo(220, 340);
    actx.lineTo(300, 440);
    actx.lineTo(380, 340);
    actx.closePath();
    actx.fill();

    const img = new Image();
    img.onload = function () {
      state.photoImage = img;
      state.photoFileName = 'Sample-Attendee-Avatar.png';
      updatePhotoStatusUI(true);
      renderCanvas();
      showToast('Sample photograph loaded!', 'success');
      setTimeout(() => updateStepView(2), 650);
    };
    img.src = avatarCanvas.toDataURL();
  }

  // ==========================================================================
  // Canvas Rendering Core
  // ==========================================================================
  function renderCanvas() {
    ctx.clearRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

    // 1. Draw Fixed Conference Template Background
    if (state.templateLoaded && state.templateImage) {
      ctx.drawImage(state.templateImage, 0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);
    } else {
      ctx.fillStyle = '#080318';
      ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);
      ctx.fillStyle = '#a855f7';
      ctx.font = '700 32px Inter, sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('Loading DevOpsDays Poster Template...', CANVAS_WIDTH / 2, CANVAS_HEIGHT / 2);
      return;
    }

    // 2. Draw Uploaded Picture (automatically fitted inside PHOTO_BOX)
    if (state.photoImage) {
      renderProfilePhoto();
    }

    // 3. Render Attendee Name below photo
    renderAttendeeName();

    // 4. Render Attendee Designation or University below name
    renderAttendeeDesignation();
  }

  /**
   * Render uploaded profile photo strictly clipped inside the central square area.
   * Automatically covers and centers inside the box without manual adjusters.
   */
  function renderProfilePhoto() {
    const box = PHOTO_BOX;
    const img = state.photoImage;

    ctx.save();

    createRoundedRectPath(ctx, box.x, box.y, box.width, box.height, box.radius);
    ctx.clip();

    ctx.fillStyle = '#0f0728';
    ctx.fill();

    const coverScale = Math.max(box.width / img.width, box.height / img.height);
    const drawW = img.width * coverScale;
    const drawH = img.height * coverScale;

    const drawX = box.centerX - drawW / 2;
    const drawY = box.centerY - drawH / 2;

    ctx.drawImage(img, drawX, drawY, drawW, drawH);
    ctx.restore();

    ctx.save();
    createRoundedRectPath(ctx, box.x, box.y, box.width, box.height, box.radius);

    ctx.lineWidth = 8;
    ctx.strokeStyle = 'rgba(217, 70, 239, 0.7)';
    ctx.shadowColor = 'rgba(217, 70, 239, 0.9)';
    ctx.shadowBlur = 18;
    ctx.stroke();

    ctx.lineWidth = 3.5;
    ctx.strokeStyle = 'rgba(255, 220, 255, 0.96)';
    ctx.shadowColor = 'rgba(255, 255, 255, 0.8)';
    ctx.shadowBlur = 6;
    ctx.stroke();

    ctx.restore();
  }

  function renderAttendeeName() {
    let rawName = (state.name || '').trim();
    if (!rawName) return;

    rawName = rawName.toUpperCase();

    const bounds = TEXT_BOUNDS;
    let targetFontSize = state.nameSize;

    ctx.font = `900 italic ${targetFontSize}px "Montserrat", sans-serif`;
    let measuredWidth = ctx.measureText(rawName).width;

    if (measuredWidth > bounds.maxWidth) {
      const scale = bounds.maxWidth / measuredWidth;
      targetFontSize = Math.max(TEXT_BOUNDS.name.minSize, Math.floor(targetFontSize * scale));
      ctx.font = `900 italic ${targetFontSize}px "Montserrat", sans-serif`;
    }

    ctx.save();
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';

    const textX = bounds.centerX;
    const textY = bounds.name.centerY;

    const grad = ctx.createLinearGradient(0, textY - targetFontSize * 0.5, 0, textY + targetFontSize * 0.5);
    grad.addColorStop(0.0, '#FFFFFF');
    grad.addColorStop(0.3, '#FFE4F8');
    grad.addColorStop(0.7, '#F472B6');
    grad.addColorStop(1.0, '#C084FC');

    ctx.shadowColor = 'rgba(217, 70, 239, 0.85)';
    ctx.shadowBlur = 32;
    ctx.fillStyle = grad;
    ctx.fillText(rawName, textX, textY);

    ctx.shadowColor = 'rgba(168, 85, 247, 0.75)';
    ctx.shadowBlur = 14;
    ctx.fillText(rawName, textX, textY);

    ctx.shadowColor = '#FFFFFF';
    ctx.shadowBlur = 4;
    ctx.fillText(rawName, textX, textY);

    ctx.restore();
  }

  function renderAttendeeDesignation() {
    const rawDesig = (state.designation || '').trim();
    if (!rawDesig) return;

    const bounds = TEXT_BOUNDS;
    let targetFontSize = state.desigSize;

    let lines = rawDesig.split('\n').map(l => l.trim()).filter(Boolean);

    ctx.font = `700 ${targetFontSize}px "Inter", "Montserrat", sans-serif`;
    if (lines.length === 1) {
      const singleWidth = ctx.measureText(lines[0]).width;
      if (singleWidth > bounds.maxWidth) {
        lines = wrapTextIntoLines(lines[0], bounds.maxWidth, targetFontSize);
      }
    }

    if (lines.length > 2) {
      lines = [lines[0], lines.slice(1).join(' � ')];
    }

    let maxLineWidth = 0;
    lines.forEach(line => {
      const w = ctx.measureText(line).width;
      if (w > maxLineWidth) maxLineWidth = w;
    });

    if (maxLineWidth > bounds.maxWidth) {
      const scale = bounds.maxWidth / maxLineWidth;
      targetFontSize = Math.max(TEXT_BOUNDS.designation.minSize, Math.floor(targetFontSize * scale));
    }

    ctx.save();
    ctx.textAlign = 'center';
    ctx.textBaseline = 'top';
    ctx.font = `700 ${targetFontSize}px "Inter", "Montserrat", sans-serif`;

    const lineHeight = targetFontSize * bounds.designation.lineHeightMultiplier;
    const totalBlockHeight = lines.length * lineHeight;
    const startY = bounds.designation.topY + (bounds.designation.maxHeight - totalBlockHeight) / 2;

    lines.forEach((line, index) => {
      const lineY = startY + index * lineHeight;

      ctx.shadowColor = 'rgba(192, 132, 252, 0.45)';
      ctx.shadowBlur = 8;
      ctx.fillStyle = index === 0 ? '#F8FAFC' : '#E2E8F0';
      ctx.fillText(line, bounds.centerX, lineY);
    });

    ctx.restore();
  }

  function wrapTextIntoLines(text, maxWidth, fontSize) {
    ctx.font = `700 ${fontSize}px "Inter", "Montserrat", sans-serif`;
    const words = text.split(' ');
    if (words.length <= 1) return [text];

    const midpoint = Math.floor(words.length / 2);
    const line1 = words.slice(0, midpoint).join(' ');
    const line2 = words.slice(midpoint).join(' ');

    return [line1, line2];
  }

  function createRoundedRectPath(context, x, y, width, height, radius) {
    context.beginPath();
    context.moveTo(x + radius, y);
    context.lineTo(x + width - radius, y);
    context.quadraticCurveTo(x + width, y, x + width, y + radius);
    context.lineTo(x + width, y + height - radius);
    context.quadraticCurveTo(x + width, y + height, x + width - radius, y + height);
    context.lineTo(x + radius, y + height);
    context.quadraticCurveTo(x, y + height, x, y + height - radius);
    context.lineTo(x, y + radius);
    context.quadraticCurveTo(x, y, x + radius, y);
    context.closePath();
  }

  // ==========================================================================
  // High-Resolution PNG Download
  // ==========================================================================
  function downloadPoster() {
    try {
      renderCanvas();

      const sanitizedName = (state.name || 'Attendee')
        .trim()
        .replace(/[^a-zA-Z0-9_-]/g, '_')
        .replace(/_+/g, '_');

      const fileName = `DevOpsDays-Islamabad-2026-${sanitizedName}.png`;

      if (dom.canvas.toBlob) {
        dom.canvas.toBlob(function (blob) {
          if (!blob) {
            triggerDataUrlDownload(fileName);
            return;
          }
          const url = URL.createObjectURL(blob);
          const link = document.createElement('a');
          link.href = url;
          link.download = fileName;
          document.body.appendChild(link);
          link.click();
          document.body.removeChild(link);
          setTimeout(() => URL.revokeObjectURL(url), 2000);
          showToast('High-resolution poster downloaded!', 'success');
        }, 'image/png', 1.0);
      } else {
        triggerDataUrlDownload(fileName);
      }
    } catch (err) {
      console.error('Download error:', err);
      showToast('Error generating poster download. Please try again.', 'error');
    }
  }

  function triggerDataUrlDownload(fileName) {
    const dataUrl = dom.canvas.toDataURL('image/png', 1.0);
    const link = document.createElement('a');
    link.href = dataUrl;
    link.download = fileName;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    showToast('Poster downloaded!', 'success');
  }

  // ==========================================================================
  // LinkedIn Sharing
  // ==========================================================================
  async function handleLinkedInShare() {
    renderCanvas();

    const shareTitle = "I'm Attending DevOpsDays Islamabad 2026!";
    const shareText = `Excited to announce that I will be attending DevOpsDays Islamabad 2026! ?? Looking forward to connecting with the DevOps, Cloud, and SRE community.\n\n#DevOpsDaysIslamabad #DevOpsDays #DevOps #CloudNative #Islamabad`;

    if (navigator.canShare && navigator.share && dom.canvas.toBlob) {
      try {
        const blob = await new Promise(resolve => dom.canvas.toBlob(resolve, 'image/png', 1.0));
        if (blob) {
          const sanitizedName = (state.name || 'Attendee').replace(/[^a-zA-Z0-9_-]/g, '_');
          const file = new File([blob], `DevOpsDays-Islamabad-2026-${sanitizedName}.png`, { type: 'image/png' });

          if (navigator.canShare({ files: [file] })) {
            await navigator.share({
              title: shareTitle,
              text: shareText,
              files: [file]
            });
            showToast('Shared successfully!', 'success');
            return;
          }
        }
      } catch (err) {
        if (err.name !== 'AbortError') {
          console.warn('Native share dismissed or unsupported:', err);
        } else {
          return;
        }
      }
    }

    dom.captionText.value = shareText;
    dom.copyTextState.textContent = 'Copy Caption';
    dom.linkedInModal.classList.add('is-open');
    dom.linkedInModal.setAttribute('aria-hidden', 'false');
  }

  function closeModal() {
    dom.linkedInModal.classList.remove('is-open');
    dom.linkedInModal.setAttribute('aria-hidden', 'true');
  }

  function copyShareCaption() {
    dom.captionText.select();
    dom.captionText.setSelectionRange(0, 99999);
    try {
      navigator.clipboard.writeText(dom.captionText.value).then(() => {
        dom.copyTextState.textContent = 'Copied! ?';
        showToast('Caption copied to clipboard!', 'success');
        setTimeout(() => {
          dom.copyTextState.textContent = 'Copy Caption';
        }, 2500);
      });
    } catch (err) {
      document.execCommand('copy');
      dom.copyTextState.textContent = 'Copied! ?';
      showToast('Caption copied to clipboard!', 'success');
    }
  }

  // ==========================================================================
  // Reset Everything
  // ==========================================================================
  function resetAll() {
    if (!confirm('Are you sure you want to reset and start over?')) {
      return;
    }

    state.photoImage = null;
    state.photoFileName = '';
    state.name = 'SYED MUHAMMAD ALI';
    state.nameSize = TEXT_BOUNDS.name.defaultSize;
    state.designation = 'Principal DevOps Architect | AWS Hero\nCloud Platform Engineering';
    state.desigSize = TEXT_BOUNDS.designation.defaultSize;

    dom.imageInput.value = '';
    dom.nameInput.value = state.name;
    dom.desigInput.value = state.designation;

    updatePhotoStatusUI(false);
    updateSizeDisplays();
    renderCanvas();
    updateStepView(1);
    showToast('Reset to initial state', 'info');
  }

  // ==========================================================================
  // Toast Notifications
  // ==========================================================================
  function showToast(message, type = 'info') {
    const toast = document.createElement('div');
    toast.className = 'toast';

    let iconSvg = '';
    if (type === 'success') {
      iconSvg = '<svg viewBox="0 0 24 24" fill="none" stroke="#10b981" stroke-width="2.5"><polyline points="20 6 9 17 4 12"/></svg>';
    } else if (type === 'error') {
      iconSvg = '<svg viewBox="0 0 24 24" fill="none" stroke="#ef4444" stroke-width="2.5"><circle cx="12" cy="12" r="10"/><line x1="12" y1="8" x2="12" y2="12"/><line x1="12" y1="16" x2="12.01" y2="16"/></svg>';
    } else {
      iconSvg = '<svg viewBox="0 0 24 24" fill="none" stroke="#d946ef" stroke-width="2.5"><circle cx="12" cy="12" r="10"/><line x1="12" y1="16" x2="12" y2="12"/><line x1="12" y1="8" x2="12.01" y2="8"/></svg>';
    }

    toast.innerHTML = `<span class="toast-icon">${iconSvg}</span><span>${escapeHtml(message)}</span>`;
    dom.toastContainer.appendChild(toast);

    requestAnimationFrame(() => toast.classList.add('show'));

    setTimeout(() => {
      toast.classList.remove('show');
      setTimeout(() => {
        if (toast.parentNode) toast.parentNode.removeChild(toast);
      }, 300);
    }, 3500);
  }

  function escapeHtml(str) {
    const div = document.createElement('div');
    div.textContent = str;
    return div.innerHTML;
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();
